BEGIN TRANSACTION;
CREATE TABLE activity(id INTEGER PRIMARY KEY, project_id INTEGER REFERENCES projects(id), occurred TEXT, description TEXT);
CREATE TABLE app_session(id INTEGER PRIMARY KEY CHECK(id=1),active INTEGER NOT NULL DEFAULT 0,started TEXT DEFAULT '',last_clean TEXT DEFAULT '');
INSERT INTO "app_session" VALUES(1,0,'','');
CREATE TABLE approval_history(id INTEGER PRIMARY KEY,approval_id INTEGER NOT NULL REFERENCES approvals(id),occurred TEXT NOT NULL,event TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE approvals(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,approval_type TEXT DEFAULT 'Work',reference TEXT DEFAULT '',discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',supplier_name TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),contract_id INTEGER REFERENCES contracts(id),description TEXT DEFAULT '',currency TEXT DEFAULT 'USD',price TEXT DEFAULT '',status TEXT DEFAULT 'Draft',submitted TEXT DEFAULT '',deadline TEXT DEFAULT '',reviewer_id INTEGER REFERENCES contacts(id),reviewed_by TEXT DEFAULT '',review_date TEXT DEFAULT '',decision_notes TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE TABLE bid_items(id INTEGER PRIMARY KEY,bid_id INTEGER NOT NULL REFERENCES bids(id),title TEXT NOT NULL,item_type TEXT DEFAULT 'Base',building_area TEXT DEFAULT '',specification TEXT DEFAULT '',material TEXT DEFAULT '',quantity_basis TEXT DEFAULT 'Manual',quantity TEXT DEFAULT '1',length TEXT DEFAULT '0',width TEXT DEFAULT '0',unit TEXT DEFAULT 'each',waste_percent TEXT DEFAULT '0',material_unit_cost TEXT DEFAULT '0',labor_hours_per_unit TEXT DEFAULT '0',labor_rate TEXT DEFAULT '0',equipment_unit_cost TEXT DEFAULT '0',subcontract_unit_cost TEXT DEFAULT '0',other_cost TEXT DEFAULT '0',included INTEGER DEFAULT 1,notes TEXT DEFAULT '');
CREATE TABLE bid_packages(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',bid_type TEXT DEFAULT 'Lump Sum',scope TEXT DEFAULT '',deadline TEXT DEFAULT '',status TEXT DEFAULT 'Draft',notes TEXT DEFAULT '');
CREATE TABLE bids(id INTEGER PRIMARY KEY,package_id INTEGER NOT NULL REFERENCES bid_packages(id),title TEXT NOT NULL,contact_id INTEGER REFERENCES contacts(id),currency TEXT DEFAULT 'USD',status TEXT DEFAULT 'Draft',received TEXT DEFAULT '',valid_until TEXT DEFAULT '',tax_percent TEXT DEFAULT '0',markup_percent TEXT DEFAULT '0',contingency_percent TEXT DEFAULT '0',discount TEXT DEFAULT '0',exclusions TEXT DEFAULT '',schedule_notes TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE TABLE budgets(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,discipline TEXT DEFAULT 'General',currency TEXT DEFAULT 'USD',base_amount TEXT DEFAULT '0.00',contingency_amount TEXT DEFAULT '0.00',status TEXT DEFAULT 'Active',notes TEXT DEFAULT '');
CREATE TABLE communications(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), contact_id INTEGER REFERENCES contacts(id), occurred TEXT NOT NULL, summary TEXT NOT NULL, follow_up TEXT DEFAULT '', status TEXT DEFAULT 'Open');
CREATE TABLE contacts(id INTEGER PRIMARY KEY, name TEXT NOT NULL, role TEXT DEFAULT '', company TEXT DEFAULT '', email TEXT DEFAULT '', phone TEXT DEFAULT '', notes TEXT DEFAULT '', discipline TEXT DEFAULT 'General');
CREATE TABLE contract_changes(id INTEGER PRIMARY KEY,contract_id INTEGER NOT NULL REFERENCES contracts(id),title TEXT NOT NULL,reference TEXT DEFAULT '',amount TEXT DEFAULT '0.00',status TEXT DEFAULT 'Proposed',approved_date TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE TABLE contracts(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,contract_number TEXT DEFAULT '',contractor_name TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),budget_id INTEGER REFERENCES budgets(id),bid_id INTEGER REFERENCES bids(id),discipline TEXT DEFAULT 'General',currency TEXT DEFAULT 'USD',original_amount TEXT DEFAULT '0.00',scope TEXT DEFAULT '',signed_date TEXT DEFAULT '',start_date TEXT DEFAULT '',end_date TEXT DEFAULT '',status TEXT DEFAULT 'Draft',notes TEXT DEFAULT '');
CREATE TABLE custom_fields(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),scope_item_id INTEGER REFERENCES scope_items(id),title TEXT NOT NULL,field_type TEXT DEFAULT 'Text',value TEXT DEFAULT '',unit TEXT DEFAULT '',is_required INTEGER DEFAULT 0,notes TEXT DEFAULT '');
CREATE TABLE documents(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, category TEXT DEFAULT 'Architectural Plans', discipline TEXT DEFAULT 'General', sheet_number TEXT DEFAULT '', drawing_type TEXT DEFAULT 'Plan Set', building_area TEXT DEFAULT '', scale TEXT DEFAULT '', designer_id INTEGER REFERENCES contacts(id), issue_purpose TEXT DEFAULT '');
CREATE TABLE finance_files(id INTEGER PRIMARY KEY,contract_id INTEGER REFERENCES contracts(id),budget_id INTEGER REFERENCES budgets(id),owner_table TEXT DEFAULT '',owner_id INTEGER,original_name TEXT NOT NULL,file_path TEXT NOT NULL,sha256 TEXT NOT NULL,byte_size INTEGER NOT NULL,added_date TEXT NOT NULL,notes TEXT DEFAULT '',CHECK((contract_id IS NOT NULL)+(budget_id IS NOT NULL)+(owner_table!='' AND owner_id IS NOT NULL)=1));
CREATE TABLE form_drafts(id TEXT PRIMARY KEY,target_table TEXT NOT NULL,row_id INTEGER,payload TEXT NOT NULL,extra TEXT NOT NULL DEFAULT '{}',updated TEXT NOT NULL);
CREATE TABLE issues(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,issue_type TEXT NOT NULL DEFAULT 'Correction',site_address TEXT DEFAULT '',location TEXT DEFAULT '',required_fix TEXT NOT NULL,description TEXT DEFAULT '',reference TEXT DEFAULT '',sheet_reference TEXT DEFAULT '',code_reference TEXT DEFAULT '',authority TEXT DEFAULT '',permit_id INTEGER REFERENCES registers(id),discipline TEXT DEFAULT 'General',contact_id INTEGER REFERENCES contacts(id),priority TEXT DEFAULT 'Normal',reported_by TEXT DEFAULT '',reported_date TEXT DEFAULT '',deadline TEXT DEFAULT '',status TEXT DEFAULT 'Open',resolved_date TEXT DEFAULT '',resolution_notes TEXT DEFAULT '',attachment_path TEXT DEFAULT '',attachment_name TEXT DEFAULT '');
CREATE TABLE meetings(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,meeting_type TEXT DEFAULT 'Coordination',meeting_date TEXT NOT NULL,start_time TEXT DEFAULT '',location TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),attendees TEXT DEFAULT '',agenda TEXT DEFAULT '',minutes TEXT DEFAULT '',decisions TEXT DEFAULT '',status TEXT DEFAULT 'Scheduled');
CREATE TABLE milestones(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, phase TEXT DEFAULT '', deadline TEXT DEFAULT '', status TEXT DEFAULT 'Planned');
CREATE TABLE permit_requirements(
 id INTEGER PRIMARY KEY, register_id INTEGER NOT NULL REFERENCES registers(id),
 title TEXT NOT NULL, source_url TEXT DEFAULT '', completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1)),
 completed_on TEXT DEFAULT '', notes TEXT DEFAULT '');
CREATE TABLE project_contacts(project_id INTEGER REFERENCES projects(id), contact_id INTEGER REFERENCES contacts(id), PRIMARY KEY(project_id,contact_id));
CREATE TABLE project_profiles(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL UNIQUE REFERENCES projects(id),title TEXT NOT NULL DEFAULT 'Project profile',use_type TEXT DEFAULT 'Undecided',project_type TEXT DEFAULT 'Undecided',occupancy TEXT DEFAULT '',parcel_number TEXT DEFAULT '',jurisdiction TEXT DEFAULT '',zoning TEXT DEFAULT '',construction_type TEXT DEFAULT '',residential_units TEXT DEFAULT '',stories TEXT DEFAULT '',floor_area TEXT DEFAULT '',area_unit TEXT DEFAULT 'sq ft',kitchen TEXT DEFAULT 'Undecided',bathroom TEXT DEFAULT 'Undecided',occupied_work TEXT DEFAULT 'Undecided',accessibility TEXT DEFAULT 'Undecided',fire_sprinklers TEXT DEFAULT 'Undecided',notes TEXT DEFAULT '');
CREATE TABLE project_section_order(project_id INTEGER NOT NULL REFERENCES projects(id),area TEXT NOT NULL CHECK(area IN ('sidebar','hidden')),section TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),PRIMARY KEY(project_id,area,section),UNIQUE(project_id,area,position));
CREATE TABLE project_sections(project_id INTEGER NOT NULL REFERENCES projects(id),section TEXT NOT NULL,hidden INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(project_id,section));
CREATE TABLE projects(id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT DEFAULT '', owner TEXT DEFAULT '', description TEXT DEFAULT '', phase TEXT DEFAULT 'Planning', status TEXT DEFAULT 'Active', archived INTEGER DEFAULT 0, updated TEXT);
CREATE TABLE rebates(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,provider TEXT DEFAULT '',program_type TEXT DEFAULT 'Rebate',scope_item_id INTEGER REFERENCES scope_items(id),eligibility TEXT DEFAULT 'Undecided',status TEXT DEFAULT 'Researching',requirements_url TEXT DEFAULT '',application_url TEXT DEFAULT '',reference TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),deadline TEXT DEFAULT '',submitted TEXT DEFAULT '',currency TEXT DEFAULT 'USD',estimated_amount TEXT DEFAULT '',approved_amount TEXT DEFAULT '',received_amount TEXT DEFAULT '',requirements TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE TABLE receipts(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,supplier_name TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),reference TEXT DEFAULT '',receipt_date TEXT DEFAULT '',discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',currency TEXT DEFAULT 'USD',estimated_amount TEXT DEFAULT '',actual_amount TEXT DEFAULT '',status TEXT DEFAULT 'Pending Review',reviewed_by TEXT DEFAULT '',review_date TEXT DEFAULT '',approval_notes TEXT DEFAULT '',notes TEXT DEFAULT '',attachment_path TEXT DEFAULT '',attachment_name TEXT DEFAULT '', budget_id INTEGER REFERENCES budgets(id), contract_id INTEGER REFERENCES contracts(id), include_in_budget INTEGER DEFAULT 1, cost_category TEXT DEFAULT 'Parts & Materials', source_type TEXT DEFAULT 'Company Purchase', purchaser_name TEXT DEFAULT '', payment_responsibility TEXT DEFAULT 'Company / Direct Cost', reimbursement_amount TEXT DEFAULT '', reimbursement_status TEXT DEFAULT 'Not Applicable', reimbursed_date TEXT DEFAULT '', reimbursement_notes TEXT DEFAULT '');
CREATE TABLE registers(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,record_type TEXT DEFAULT 'RFI',reference TEXT DEFAULT '',discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),status TEXT DEFAULT 'Open',submitted TEXT DEFAULT '',deadline TEXT DEFAULT '',response TEXT DEFAULT '',notes TEXT DEFAULT '', jurisdiction_type TEXT DEFAULT 'City', jurisdiction_name TEXT DEFAULT '', department TEXT DEFAULT '', application_url TEXT DEFAULT '', requirements_url TEXT DEFAULT '', requirements_reviewed INTEGER DEFAULT 0);
CREATE TABLE scope_items(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,category TEXT DEFAULT 'Custom',discipline TEXT DEFAULT 'General',applicability TEXT DEFAULT 'Undecided',system_type TEXT DEFAULT '',energy_source TEXT DEFAULT 'Undecided',status TEXT DEFAULT 'Not Started',building_area TEXT DEFAULT '',manufacturer TEXT DEFAULT '',model TEXT DEFAULT '',quantity TEXT DEFAULT '',unit TEXT DEFAULT '',specifications TEXT DEFAULT '',requirements TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),deadline TEXT DEFAULT '',hidden INTEGER DEFAULT 0,notes TEXT DEFAULT '');
CREATE TABLE tasks(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, deadline TEXT DEFAULT '', priority TEXT DEFAULT 'Normal', contact_id INTEGER REFERENCES contacts(id), status TEXT DEFAULT 'Not Started', notes TEXT DEFAULT '', discipline TEXT DEFAULT 'General', building_area TEXT DEFAULT '', meeting_id INTEGER REFERENCES meetings(id));
CREATE TABLE versions(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES documents(id), revision TEXT NOT NULL, submitted TEXT DEFAULT '', status TEXT DEFAULT 'Draft', requirements TEXT DEFAULT '', file_path TEXT DEFAULT '', resubmission INTEGER DEFAULT 0, created TEXT, UNIQUE(document_id,revision));
CREATE TABLE work_orders(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,reference TEXT DEFAULT '',site_address TEXT DEFAULT '',currency TEXT DEFAULT 'USD',job_valuation TEXT DEFAULT '',permit_fee TEXT DEFAULT '',valuation_basis TEXT DEFAULT 'Estimated',fee_status TEXT DEFAULT 'Unknown',contractor_name TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),contract_id INTEGER REFERENCES contracts(id),permit_id INTEGER REFERENCES registers(id),jurisdiction_type TEXT DEFAULT 'Other',jurisdiction_name TEXT DEFAULT '',discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',status TEXT DEFAULT 'Draft',issued_date TEXT DEFAULT '',start_date TEXT DEFAULT '',deadline TEXT DEFAULT '',scope TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE TABLE work_packages(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),status TEXT DEFAULT 'Not Started',deadline TEXT DEFAULT '',scope TEXT DEFAULT '',requirements TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE UNIQUE INDEX one_award_per_package ON bids(package_id) WHERE status='Awarded';
CREATE INDEX work_project ON work_packages(project_id);
CREATE INDEX meetings_project ON meetings(project_id);
CREATE INDEX register_project ON registers(project_id);
CREATE INDEX bid_package_project ON bid_packages(project_id);
CREATE INDEX bids_package ON bids(package_id);
CREATE INDEX items_bid ON bid_items(bid_id);
CREATE INDEX requirements_permit ON permit_requirements(register_id);
CREATE INDEX receipts_project ON receipts(project_id);
CREATE INDEX issues_project ON issues(project_id);
CREATE INDEX issues_status ON issues(status);
CREATE UNIQUE INDEX one_contract_per_bid ON contracts(bid_id) WHERE bid_id IS NOT NULL;
CREATE INDEX contract_project ON contracts(project_id);
CREATE INDEX budget_project ON budgets(project_id);
CREATE INDEX scope_project ON scope_items(project_id);
CREATE INDEX rebate_project ON rebates(project_id);
CREATE INDEX approvals_project ON approvals(project_id);
CREATE INDEX work_orders_project ON work_orders(project_id);
COMMIT;
PRAGMA user_version=11;
